namespace MultiTenantInventory.Api.Models;

public class Product
{
    public int Id { get; set; }

    public string Name { get; set; } = string.Empty;

    public string? Description { get; set; }

    public int Quantity { get; set; }

    public decimal Price { get; set; }

    // S3 object key, e.g. "tenants/1/products/10/laptop.jpg". Generated by the backend only.
    public string? ImageKey { get; set; }

    // Every product belongs to exactly one tenant. Always set from TenantContext, never from the client.
    public int TenantId { get; set; }
    public Tenant? Tenant { get; set; }

    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

    public DateTime UpdatedAt { get; set; } = DateTime.UtcNow;
}
